### Configure Organization Roles with API Key Permissions (TypeScript)

Source: https://github.com/better-auth/better-auth/blob/main/docs/content/docs/plugins/api-key/advanced.mdx

This snippet demonstrates how to define access control statements and roles for API key operations within an organization plugin setup, granting different permissions (create, read, update, delete) based on the role.

```ts
import { betterAuth } from "better-auth"
import { organization } from "better-auth/plugins"
import { apiKey } from "@better-auth/api-key"
import { createAccessControl } from "better-auth/plugins/access"

// Define your access control statements including apiKey
const statements = {
  // ... other statements
  // Add apiKey permissions
  apiKey: ["create", "read", "update", "delete"], // [!code highlight]
} as const;

const ac = createAccessControl(statements);

// Define roles with specific apiKey permissions
const adminRole = ac.newRole({
  // ... other statements
  // Admins can manage API keys
  apiKey: ["create", "read", "update", "delete"], // [!code highlight]
});

const memberRole = ac.newRole({
  // ... other statements
  // Members can only view API keys
  apiKey: ["read"], // [!code highlight]
});

export const auth = betterAuth({
  plugins: [
    organization({
      ac,
      roles: {
        admin: adminRole,
        member: memberRole,
      },
      async sendInvitationEmail() {},
    }),
    apiKey([
      {
        configId: "org-keys",
        defaultPrefix: "org_",
        references: "organization",
      },
    ]),
  ],
});
```

