import { adminRole, memberRole, ownerRole } from "./auth";

export const DASHBOARD_PAGE_PATH = "/dashboard";
export const PROTECTED_PREFIXES = ["/api/dashboard", DASHBOARD_PAGE_PATH];

export const LOGIN_PATH = "/login";

export type DashboardCapability =
  | "analytics:read"
  | "content:manage"
  | "content:read"
  | "files:manage"
  | "files:read"
  | "operations:read"
  | "settings:manage"
  | "shortlinks:manage"
  | "shortlinks:read";

type AnyRole = typeof adminRole | typeof memberRole | typeof ownerRole;

const ROLES: Record<string, AnyRole> = {
  admin: adminRole,
  member: memberRole,
  owner: ownerRole,
};

type CapabilityResource =
  | "analytics"
  | "content"
  | "files"
  | "operations"
  | "settings"
  | "shortlinks";

const CAPABILITY_REQUEST: Record<
  DashboardCapability,
  Partial<Record<CapabilityResource, Array<"manage" | "read">>>
> = {
  "analytics:read": { analytics: ["read"] },
  "content:manage": { content: ["manage"] },
  "content:read": { content: ["read"] },
  "files:manage": { files: ["manage"] },
  "files:read": { files: ["read"] },
  "operations:read": { operations: ["read"] },
  "settings:manage": { settings: ["manage"] },
  "shortlinks:manage": { shortlinks: ["manage"] },
  "shortlinks:read": { shortlinks: ["read"] },
};

export function isProtectedPath(pathname: string): boolean {
  return PROTECTED_PREFIXES.some(
    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
  );
}

export function memberHasCapability(
  role: string,
  capability: DashboardCapability,
): boolean {
  const roleDefinition = ROLES[role];
  if (!roleDefinition) return false;
  return roleDefinition.authorize(CAPABILITY_REQUEST[capability]).success;
}

export function memberCanRead(
  resource: "analytics" | "content" | "files" | "operations" | "shortlinks",
  role: string,
): boolean {
  return memberHasCapability(role, `${resource}:read`);
}

export function memberCanManage(
  resource: "content" | "files" | "settings" | "shortlinks",
  role: string,
): boolean {
  return memberHasCapability(role, `${resource}:manage`);
}

